function reverseSearch(q){var source=String(q||'').trim().toLowerCase();if(!source)return '';if(Object.prototype.hasOwnProperty.call(reverseQueryCache,source))return reverseQueryCache[source];var data=buildSearchReverse();if(Object.prototype.hasOwnProperty.call(data.map,source))return reverseQueryCache[source]=data.map[source];var pool=data.byFirst[source.charAt(0)]||data.keys,best=null,i,k;for(i=0;i<pool.length;i++){k=pool[i];if(k.indexOf(source)>=0&&(!best||k.length<best.length))best=k}if(best)return reverseQueryCache[source]=data.map[best];var t=source,replacements=[];for(i=0;i<pool.length;i++){k=pool[i];if(t.indexOf(k)>=0)replacements.push(k)}replacements.sort(function(a,b){return b.length-a.length});for(i=0;i<replacements.length;i++){k=replacements[i];t=t.split(k).join(data.map[k])}return reverseQueryCache[source]=t}
